@@ -0,0 +1,83 @@
+import { describe, expect, it } from 'vitest';
+import type { Message } from '@earendil-works/pi-ai';
+import { SessionManager } from '@earendil-works/pi-coding-agent';
+import { AgentContext, type AgentTrajectoryInput } from '../agentContext';
+
+const trajectory = (): AgentTrajectoryInput => ({
+  agentType: 'codex', sourceSessionId: 'coding-session', format: 'messages-v1', fromEntryId: 'u', throughEntryId: 'done',
+  entries: [
+    { id: 'u', parentId: null, message: { role: 'user', content: [{ type: 'text', text: 'Inspect the save flow' }] } },
+    { id: 'call', parentId: 'u', message: { role: 'assistant', content: [
+      { type: 'text', text: 'Reading the implementation' },
+      { type: 'toolCall', id: 'read-1', name: 'read', arguments: { path: 'save.ts', limit: 10 } }
+    ] } },
+    { id: 'result', parentId: 'call', message: { role: 'toolResult', toolCallId: 'read-1', toolName: 'read',
+      content: [{ type: 'text', text: 'save()\n  flush()' }] } },
+    { id: 'discarded', parentId: 'u', message: { role: 'assistant', content: [{ type: 'text', text: 'Unselected branch' }] } },
+    { id: 'done', parentId: 'result', message: { role: 'assistant', content: [{ type: 'text', text: 'Save flushes storage.' }] } }
+  ]
+});
+
+describe('AgentContext', () => {
+  it('captures only the selected branch and seeds a real Pi manager with coherent structured history', () => {
+    const input = trajectory(), context = AgentContext.fromTrajectory(input);
+    const messages: Message[] = context.toPiMessages(); // Compile-time compatibility with installed Pi SDK.
+    const manager = SessionManager.inMemory('/tmp');
+    messages.forEach(message => manager.appendMessage(message));
+    expect(manager.buildSessionContext().messages).toEqual(messages);
+    expect(messages.map(message => message.role)).toEqual(['user', 'assistant', 'toolResult', 'assistant']);
+    expect(JSON.stringify(messages)).not.toContain('Unselected branch');
+    expect(messages[2]).toMatchObject({ content: [{ text: 'save()\n  flush()' }], toolCallId: 'read-1' });
+    expect(AgentContext.fromSnapshot(structuredClone(context.toSnapshot())).toPiMessages()).toEqual(messages);
+    expect(input.entries[0].message.timestamp).toBeUndefined();
+  });
+
+  it('is immutable through both inputs and outputs and detects snapshot tampering', () => {
+    const input = trajectory(), context = AgentContext.fromTrajectory(input), before = context.toSnapshot();
+    input.entries[0].message.content.length = 0;
+    const snapshot = context.toSnapshot(); snapshot.source.agentType = 'claude';
+    expect(() => AgentContext.fromSnapshot(snapshot)).toThrow('hash mismatch');
+    context.toPiMessages()[0].content.length = 0;
+    expect(context.toSnapshot()).toEqual(before);
+  });
+
+  it('hashes canonical arguments and includes source agent identity', () => {
+    const input = trajectory(), first = AgentContext.fromTrajectory(input);
+    const message = input.entries[1].message;
+    if (message.role !== 'assistant' || message.content[1].type !== 'toolCall') throw Error('fixture');
+    message.content[1].arguments = { limit: 10, path: 'save.ts' };
+    expect(AgentContext.fromTrajectory(input).contentHash).toBe(first.contentHash);
+    expect(AgentContext.fromTrajectory({ ...input, agentType: 'claude' }).contentHash).not.toBe(first.contentHash);
+  });
+
+  it('rejects orphan results, missing results, mismatched names and duplicate calls', () => {
+    expect(() => AgentContext.fromTrajectory({ ...trajectory(), fromEntryId: 'result' })).toThrow('orphan');
+    expect(() => AgentContext.fromTrajectory({ ...trajectory(), throughEntryId: 'call' })).toThrow('before tool results');
+    const mismatch = trajectory();
+    if (mismatch.entries[2].message.role === 'toolResult') mismatch.entries[2].message.toolName = 'other';
+    expect(() => AgentContext.fromTrajectory(mismatch)).toThrow('mismatched');
+    const duplicate = trajectory(); duplicate.entries[4].message = structuredClone(duplicate.entries[1].message);
+    expect(() => AgentContext.fromTrajectory(duplicate)).toThrow('duplicate tool call');
+    const missing = trajectory(); missing.entries[4].parentId = 'call';
+    expect(() => AgentContext.fromTrajectory(missing)).toThrow('missing tool results');
+  });
+
+  it('rejects invalid branch ranges, duplicate entries, cycles and missing entries', () => {
+    expect(() => AgentContext.fromTrajectory({ ...trajectory(), fromEntryId: 'discarded' })).toThrow('one branch');
+    const duplicate = trajectory(); duplicate.entries.push(duplicate.entries[0]);
+    expect(() => AgentContext.fromTrajectory(duplicate)).toThrow('duplicate entry');
+    const cycle = trajectory(); cycle.entries[2].parentId = 'done';
+    expect(() => AgentContext.fromTrajectory(cycle)).toThrow('cyclic');
+    const missing = trajectory(); missing.entries[2].parentId = 'missing';
+    expect(() => AgentContext.fromTrajectory(missing)).toThrow('missing entry');
+  });
+
+  it('supports slices starting after omitted ancestors and rejects unsupported records and oversized data', () => {
+    expect(AgentContext.fromTrajectory({ ...trajectory(), fromEntryId: 'done' }).toSnapshot().messages).toHaveLength(1);
+    expect(() => AgentContext.fromTrajectory({ ...trajectory(), format: 'codex-jsonl' })).toThrow();
+    const large = trajectory(); large.entries[0].message = { role: 'user', content: [{ type: 'text', text: 'x'.repeat(2_100_000) }] };
+    expect(() => AgentContext.fromTrajectory(large)).toThrow('TOO_LARGE');
+    const unknown = trajectory();
+    expect(() => AgentContext.fromTrajectory({ ...unknown, agentType: '' })).toThrow();
+  });
+});
diff --git a/domain/core/agents/agentContext.ts b/domain/core/agents/agentContext.ts
new file mode 100644
index 00000000..95c135b5
--- /dev/null
+++ b/domain/core/agents/agentContext.ts
@@ -0,0 +1,113 @@
+import { z } from 'zod';
+import { sha256 } from '../sha256';
+
+export const AGENT_CONTEXT_MAX_BYTES = 2 * 1024 * 1024;
+const id = z.string().min(1).max(200);
+const text = z.object({ type: z.literal('text'), text: z.string().max(1_000_000) }).strict();
+const toolCall = z.object({ type: z.literal('toolCall'), id, name: id, arguments: z.record(z.string(), z.json()) }).strict();
+const timestamp = z.number().int().nonnegative().default(0);
+export const agentContextMessageSchema = z.discriminatedUnion('role', [
+  z.object({ role: z.literal('user'), content: z.array(text).min(1).max(1000), timestamp }).strict(),
+  z.object({ role: z.literal('assistant'), content: z.array(z.union([text, toolCall])).min(1).max(1000), timestamp }).strict(),
+  z.object({ role: z.literal('toolResult'), toolCallId: id, toolName: id,
+    content: z.array(text).min(1).max(1000), isError: z.boolean().default(false), timestamp }).strict()
+]);
+export type AgentContextMessage = z.infer<typeof agentContextMessageSchema>;
+const entrySchema = z.object({ id, parentId: id.nullable(), message: agentContextMessageSchema }).strict();
+export const agentTrajectorySchema = z.object({
+  agentType: z.string().regex(/^[a-z][a-z0-9_-]{0,63}$/), sourceSessionId: id,
+  format: z.literal('messages-v1'), fromEntryId: id, throughEntryId: id,
+  entries: z.array(entrySchema).min(1).max(2000)
+}).strict();
+export type AgentTrajectoryInput = z.input<typeof agentTrajectorySchema>;
+const snapshotDataSchema = z.object({
+  version: z.literal(1),
+  source: agentTrajectorySchema.pick({ agentType: true, sourceSessionId: true, format: true }),
+  range: agentTrajectorySchema.pick({ fromEntryId: true, throughEntryId: true }),
+  messages: z.array(agentContextMessageSchema).min(1).max(2000)
+}).strict();
+export const agentContextSnapshotSchema = snapshotDataSchema.extend({ contentHash: z.string().regex(/^[a-f0-9]{64}$/) });
+export type AgentContextSnapshot = z.infer<typeof agentContextSnapshotSchema>;
+
+/** Canonical JSON also stabilizes tool arguments whose object key order differs. */
+function canonical(value: unknown): string {
+  if (Array.isArray(value)) return `[${value.map(canonical).join(',')}]`;
+  if (value !== null && typeof value === 'object') return `{${Object.keys(value).sort()
+    .map(key => `${JSON.stringify(key)}:${canonical((value as Record<string, unknown>)[key])}`).join(',')}}`;
+  return JSON.stringify(value);
+}
+function bounded(input: unknown) {
+  if (new TextEncoder().encode(JSON.stringify(input)).byteLength > AGENT_CONTEXT_MAX_BYTES)
+    throw Error('AGENT_CONTEXT_TOO_LARGE: context exceeds 2 MiB');
+}
+function validateMessages(messages: AgentContextMessage[]) {
+  const pending = new Map<string, string>(), seen = new Set<string>();
+  for (const message of messages) {
+    if (message.role === 'toolResult') {
+      if (pending.get(message.toolCallId) !== message.toolName)
+        throw Error('INVALID_AGENT_CONTEXT: orphan, duplicate or mismatched tool result');
+      pending.delete(message.toolCallId);
+    } else {
+      if (pending.size) throw Error('INVALID_AGENT_CONTEXT: missing tool results before next message');
+      if (message.role === 'assistant') for (const block of message.content) if (block.type === 'toolCall') {
+        if (seen.has(block.id)) throw Error('INVALID_AGENT_CONTEXT: duplicate tool call ID');
+        seen.add(block.id); pending.set(block.id, block.name);
+      }
+    }
+  }
+  if (pending.size) throw Error('INVALID_AGENT_CONTEXT: slice ends before tool results');
+}
+
+/** Captured trajectory value. All parsing/conversion lives here; no SDK or I/O dependency. */
+export class AgentContext {
+  readonly #snapshot: AgentContextSnapshot;
+  private constructor(snapshot: AgentContextSnapshot) { this.#snapshot = structuredClone(snapshot); }
+  get contentHash() { return this.#snapshot.contentHash; }
+
+  static fromTrajectory(raw: unknown): AgentContext {
+    bounded(raw);
+    const input = agentTrajectorySchema.parse(raw);
+    const entries = new Map(input.entries.map(entry => [entry.id, entry]));
+    if (entries.size !== input.entries.length) throw Error('INVALID_AGENT_CONTEXT: duplicate entry ID');
+    const selected: AgentContextMessage[] = [], visited = new Set<string>();
+    let cursor: string | null = input.throughEntryId;
+    while (cursor !== null) {
+      if (visited.has(cursor)) throw Error('INVALID_AGENT_CONTEXT: cyclic trajectory');
+      visited.add(cursor);
+      const entry = entries.get(cursor);
+      if (!entry) throw Error('INVALID_AGENT_CONTEXT: missing entry on selected branch');
+      selected.push(entry.message);
+      if (cursor === input.fromEntryId) break;
+      cursor = entry.parentId;
+    }
+    if (cursor !== input.fromEntryId) throw Error('INVALID_AGENT_CONTEXT: range is not on one branch');
+    const messages = selected.reverse();
+    validateMessages(messages);
+    const data = snapshotDataSchema.parse({ version: 1,
+      source: { agentType: input.agentType, sourceSessionId: input.sourceSessionId, format: input.format },
+      range: { fromEntryId: input.fromEntryId, throughEntryId: input.throughEntryId }, messages });
+    return new AgentContext({ ...data, contentHash: sha256(canonical(data)) });
+  }
+
+  static fromSnapshot(raw: unknown): AgentContext {
+    bounded(raw);
+    const snapshot = agentContextSnapshotSchema.parse(raw);
+    const { contentHash, ...data } = snapshot;
+    if (contentHash !== sha256(canonical(data))) throw Error('INVALID_AGENT_CONTEXT: content hash mismatch');
+    validateMessages(snapshot.messages);
+    return new AgentContext(snapshot);
+  }
+
+  toSnapshot(): AgentContextSnapshot { return structuredClone(this.#snapshot); }
+
+  toPiMessages() {
+    return this.toSnapshot().messages.map(message => {
+      if (message.role !== 'assistant') return message;
+      // Synthetic provenance marks imported history; it never selects the run's model.
+      return { ...message, api: 'openai-responses' as const, provider: 'agent-context', model: this.#snapshot.source.agentType,
+        stopReason: message.content.some(block => block.type === 'toolCall') ? 'toolUse' as const : 'stop' as const,
+        usage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, totalTokens: 0,
+          cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 } } };
+    });
+  }
+}
